INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-017',unit_id,'quiz-topic-neuro-ap1','Que ponto do meato acústico externo integra o plano de Frankfurt?',NULL,'A linha sagital násion–inion acompanha o plano sagital do crânio desde o násion, anteriormente, até ao inion, posteriormente. A linha de Reid ou plano de Frankfurt passa pelo bordo inferior da órbita e pelo bordo superior do meato acústico externo, no <strong>porion</strong>. A linha infraorbitomeática estende-se do bordo inferior da órbita até ao centro do meato acústico externo, no ponto auricular.<p><small>Gray’s Anatomy, 42.ª ed., p. 395.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
